window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cd967f33b5fef623"]={"versions": [{"id": "FIG-cd967f33b5fef623", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Architekturübersicht zur Einbettung der Timing-Analyse und -Bewertung (Timing-analysis and assessment) in das V-Modell der automobilen Systementwicklung. Das Diagramm veranschaulicht das Zusammenspiel zwischen den Phasen der Spezifikation und des Designs (absteigender linker Ast), der Implementierung (Basis) sowie der Integrations- und Teststufen (aufsteigender rechter Ast) mit einer zentralen Analyseinstanz für zeitliche Eigenschaften über den gesamten Entwicklungszyklus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Hauptelemente:</p>\n<ul class=\"fig-list\"><li>Zentrale Analyseeinheit: <code>Timing-analysis and assessment</code> mit schematischer Darstellung von Task- und Interrupt-Ablaufdiagrammen (Gantt-/Trace-Ansicht mit Signalverläufen und Task-Zuständen).\n</li><li>Entwicklungsphasen des V-Modells:\n<ul class=\"fig-list\"><li>Entwurfs- und Spezifikationsphasen: <code>System Design</code>, <code>System Specification</code>, <code>Component Specification</code>, <code>Component Design</code>.\n</li><li>Realisierung: <code>Implementation</code>.\n</li><li>Integrations- und Testphasen: <code>Integration Test Component</code>, <code>Integration Test Vehicle</code> (begleitet von der Achse <code>Design Verification</code>).\n</li></ul>\n</li><li>Dokumenten- und Datenartefakte (als umgeknickte Dokumenten-Icons dargestellt):\n<ul class=\"fig-list\"><li><code>Criteria and limits for system design</code>: Vorgaben für das Gesamtsystemdesign.\n</li><li><code>Functional requirements and boundary conditions</code>: Anforderungen und Randbedingungen für die Systemspezifikation.\n</li><li><code>Boundary conditions for implementation</code>: Randbedingungen für Komponentendesign und Implementierung.\n</li><li><code>Test cases and test criteria</code>: Spezifische Testfälle und Kriterien für Fahrzeug-Integrationstests.\n</li><li><code>Measurements for refinement and verification of timing requirements.</code>: Messergebnisse aus Fahrzeugtests zur Rückführung in die Timing-Bewertung.\n</li></ul>\n</li><li>Gerichtete Pfeilverbindungen: Informations- und Vorgabeflüsse zwischen der zentralen Analyseeinheit, den Artefakten und den V-Modell-Phasen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beschreibt einen kontinuierlichen, iterativen Feedback- und Kontrollzyklus:</p>\n<ol class=\"fig-list\"><li>Vorgabe von Systemkriterien: Aus der Timing-Analyse fließen <code>Criteria and limits for system design</code> in die Phase <code>System Design</code>.\n</li><li>Detaillierung von Anforderungen: Aus der Analyse werden funktionale Anforderungen und Randbedingungen (<code>Functional requirements and boundary conditions</code>) an die <code>System Specification</code> sowie an die <code>Component Specification</code> weitergegeben.\n</li><li>Implementierungsrandbedingungen: Die Timing-Analyse liefert <code>Boundary conditions for implementation</code> an <code>Component Design</code> und die <code>Implementation</code>.\n</li><li>Testdefinition und -verifikation: Aus der Analyse werden <code>Test cases and test criteria</code> an den <code>Integration Test Vehicle</code> übermittelt sowie Analysebezüge zum <code>Integration Test Component</code> hergestellt.\n</li><li>Verifikations- und Messrückführung: Aus den Tests des Gesamtfahrzeugs (<code>Integration Test Vehicle</code>) werden Messwerte (<code>Measurements for refinement and verification of timing requirements.</code>) zurück in die <code>Timing-analysis and assessment</code> eingespeist, um Zeitmodelle zu verfeinern und Timing-Anforderungen iterativ zu verifizieren.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt methodischen und informativen Leitfadencharakter im Rahmen des AUTOSAR-Timing-Modells (AUTOSAR_TR_TimingAnalysis). Es dient Entwicklern, Systemarchitekten und Integratoren als Referenz dafür, zu welchen Entwicklungszeitpunkten Timing-Vorgaben generiert, verfeinert oder validiert werden müssen. Es betont die Notwendigkeit, Timing-Anforderungen nicht erst bei der Fahrzeugerprobung spätzyklisch zu analysieren, sondern durchgängig von der frühen Spezifikationsphase bis zu Komponenten- und Gesamtfahrzeugtests nachzuhalten und mit realen Messungen abzugleichen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-599e419b4f2ade15", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Architekturübersicht zur Einbettung der Timing-Analyse und -Bewertung (Timing-analysis and assessment) in das V-Modell der automobilen Systementwicklung. Das Diagramm veranschaulicht das Zusammenspiel zwischen den Phasen der Spezifikation und des Designs (absteigender linker Ast), der Implementierung (Basis) sowie der Integrations- und Teststufen (aufsteigender rechter Ast) mit einer zentralen Analyseinstanz für zeitliche Eigenschaften über den gesamten Entwicklungszyklus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Hauptelemente:</p>\n<ul class=\"fig-list\"><li>Zentrale Analyseeinheit: <code>Timing-analysis and assessment</code> mit schematischer Darstellung von Task- und Interrupt-Ablaufdiagrammen (Gantt-/Trace-Ansicht mit Signalverläufen und Task-Zuständen).\n</li><li>Entwicklungsphasen des V-Modells:\n<ul class=\"fig-list\"><li>Entwurfs- und Spezifikationsphasen: <code>System Design</code>, <code>System Specification</code>, <code>Component Specification</code>, <code>Component Design</code>.\n</li><li>Realisierung: <code>Implementation</code>.\n</li><li>Integrations- und Testphasen: <code>Integration Test Component</code>, <code>Integration Test Vehicle</code> (begleitet von der Achse <code>Design Verification</code>).\n</li></ul>\n</li><li>Dokumenten- und Datenartefakte (als umgeknickte Dokumenten-Icons dargestellt):\n<ul class=\"fig-list\"><li><code>Criteria and limits for system design</code>: Vorgaben für das Gesamtsystemdesign.\n</li><li><code>Functional requirements and boundary conditions</code>: Anforderungen und Randbedingungen für die Systemspezifikation.\n</li><li><code>Boundary conditions for implementation</code>: Randbedingungen für Komponentendesign und Implementierung.\n</li><li><code>Test cases and test criteria</code>: Spezifische Testfälle und Kriterien für Fahrzeug-Integrationstests.\n</li><li><code>Measurements for refinement and verification of timing requirements.</code>: Messergebnisse aus Fahrzeugtests zur Rückführung in die Timing-Bewertung.\n</li></ul>\n</li><li>Gerichtete Pfeilverbindungen: Informations- und Vorgabeflüsse zwischen der zentralen Analyseeinheit, den Artefakten und den V-Modell-Phasen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beschreibt einen kontinuierlichen, iterativen Feedback- und Kontrollzyklus:</p>\n<ol class=\"fig-list\"><li>Vorgabe von Systemkriterien: Aus der Timing-Analyse fließen <code>Criteria and limits for system design</code> in die Phase <code>System Design</code>.\n</li><li>Detaillierung von Anforderungen: Aus der Analyse werden funktionale Anforderungen und Randbedingungen (<code>Functional requirements and boundary conditions</code>) an die <code>System Specification</code> sowie an die <code>Component Specification</code> weitergegeben.\n</li><li>Implementierungsrandbedingungen: Die Timing-Analyse liefert <code>Boundary conditions for implementation</code> an <code>Component Design</code> und die <code>Implementation</code>.\n</li><li>Testdefinition und -verifikation: Aus der Analyse werden <code>Test cases and test criteria</code> an den <code>Integration Test Vehicle</code> übermittelt sowie Analysebezüge zum <code>Integration Test Component</code> hergestellt.\n</li><li>Verifikations- und Messrückführung: Aus den Tests des Gesamtfahrzeugs (<code>Integration Test Vehicle</code>) werden Messwerte (<code>Measurements for refinement and verification of timing requirements.</code>) zurück in die <code>Timing-analysis and assessment</code> eingespeist, um Zeitmodelle zu verfeinern und Timing-Anforderungen iterativ zu verifizieren.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt methodischen und informativen Leitfadencharakter im Rahmen des AUTOSAR-Timing-Modells (AUTOSAR_TR_TimingAnalysis). Es dient Entwicklern, Systemarchitekten und Integratoren als Referenz dafür, zu welchen Entwicklungszeitpunkten Timing-Vorgaben generiert, verfeinert oder validiert werden müssen. Es betont die Notwendigkeit, Timing-Anforderungen nicht erst bei der Fahrzeugerprobung spätzyklisch zu analysieren, sondern durchgängig von der frühen Spezifikationsphase bis zu Komponenten- und Gesamtfahrzeugtests nachzuhalten und mit realen Messungen abzugleichen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cd967f33b5fef623", "to": "FIG-599e419b4f2ade15", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
